package com.aetherarc.aether;
import android.app.Activity; import android.os.Bundle; import android.webkit.*; import org.json.JSONObject; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity { private WebView webView; @Override protected void onCreate(Bundle b){super.onCreate(b);webView=new WebView(this);WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);webView.setWebViewClient(new WebViewClient());webView.addJavascriptInterface(new AetherBridge(),"AndroidAether");setContentView(webView);webView.loadUrl("file:///android_asset/index.html");} private final class AetherBridge { @JavascriptInterface public String getBackendUrl(){return BuildConfig.AETHER_BACKEND_URL;} @JavascriptInterface public void postJson(final String id,final String url,final String auth,final String body){new Thread(()->{boolean ok=false;int code=0;String response;try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(20000);c.setReadTimeout(120000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.setRequestProperty("Accept","application/json");if(auth!=null&&!auth.isEmpty())c.setRequestProperty("Authorization",auth);byte[] bytes=body.getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream o=c.getOutputStream()){o.write(bytes);}code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();response=readAll(in);ok=code>=200&&code<300;c.disconnect();}catch(Exception e){response=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}final String r=build(ok,code,response);webView.post(()->webView.evaluateJavascript("window.__aetherNativeResponse("+JSONObject.quote(id)+","+JSONObject.quote(r)+")",null));}).start();} } private static String readAll(InputStream in)throws Exception{if(in==null)return "";StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)b.append(l);}return b.toString();} private static String build(boolean ok,int code,String body){try{JSONObject o=new JSONObject();o.put("ok",ok);o.put("code",code);o.put("body",body==null?"":body);return o.toString();}catch(Exception e){return "{\"ok\":false,\"code\":500,\"body\":\"bridge error\"}";}} @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}}
